<script setup lang="ts">import { reactive, ref } from 'vue';import { useRouter } from 'vue-router';const router=useRouter();const isSaving=ref(false);const form=reactive({title:'',content:'',tags:[] as string[],status:'draft'});async function save(){isSaving.value=true;try{await new Promise(resolve=>setTimeout(resolve,150));router.push('/manage/knowledge')}finally{isSaving.value=false}};</script>
<template><header class="page-head"><h1 class="page-title">知识编辑器</h1><el-button type="primary" :loading="isSaving" @click="save">保存</el-button></header><el-form label-position="top"><el-form-item label="标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="正文（支持 Markdown）"><el-input v-model="form.content" type="textarea" :rows="14"/></el-form-item><el-form-item label="标签"><el-select v-model="form.tags" multiple allow-create default-first-option/></el-form-item><el-form-item label="状态"><el-radio-group v-model="form.status"><el-radio value="draft">草稿</el-radio><el-radio value="published">发布</el-radio></el-radio-group></el-form-item></el-form></template>
